import { useEffect, useState } from "react";
import { API_BASE } from "../api";

/**
 * Dataset download. Both files are generated by the backend from the loaded
 * database (see /api/download/* in server.js), so they always match what the
 * rest of the site shows; this page only describes them and links to them.
 */

const fmtInt = (n) => Number(n).toLocaleString("en-US");
const fmtSize = (bytes) => {
  if (!bytes) return "—";
  return bytes >= 1024 * 1024 ? `${(bytes / 1024 / 1024).toFixed(1)} MB` : `${Math.round(bytes / 1024)} KB`;
};

export default function Download() {
  const [info, setInfo] = useState(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let cancelled = false;
    fetch(`${API_BASE}/api/download/info`)
      .then((r) => (r.ok ? r.json() : Promise.reject(new Error(r.status))))
      .then((d) => { if (!cancelled) setInfo(d); })
      .catch(() => { if (!cancelled) setFailed(true); });
    return () => { cancelled = true; };
  }, []);

  const files = [
    {
      id: "csv",
      badge: "CSV",
      title: "Full dataset",
      desc: "One row per peptide: identifiers, sequence, activity, validation status, source organism and cross-references. Opens in Excel, Python or R.",
      meta: info && [
        ["Entries", fmtInt(info.entries)],
        ["Columns", String(info.columns.length)],
        ["Encoding", "UTF-8"],
        ["Size", fmtSize(info.csvBytes)],
      ],
      href: `${API_BASE}/api/download/peptides.csv`,
      cta: "Download CSV",
    },
    {
      id: "fasta",
      badge: "FASTA",
      title: "Sequences",
      desc: "Every sequence with its ADAM ID and peptide name as the header. Ready for BLAST, MMseqs2 or the prediction tools on this site.",
      meta: info && [
        ["Sequences", fmtInt(info.fastaSequences)],
        ["Header", "ADAM ID + name"],
        ["Line width", "60 residues"],
        ["Size", fmtSize(info.fastaBytes)],
      ],
      href: `${API_BASE}/api/download/peptides.fasta`,
      cta: "Download FASTA",
    },
  ];

  return (
    <>
      <style>{`
        .dl-hero { background: #2a2a2a; color: #fff; padding: 56px 48px 60px; position: relative; overflow: hidden; }
        .dl-hero::before {
          content: ''; position: absolute; inset: 0; pointer-events: none;
          background:
            repeating-linear-gradient(90deg, rgba(255,255,255,0.02) 0px, rgba(255,255,255,0.02) 1px, transparent 1px, transparent 60px),
            repeating-linear-gradient(180deg, rgba(255,255,255,0.02) 0px, rgba(255,255,255,0.02) 1px, transparent 1px, transparent 60px);
        }
        .dl-inner { max-width: 1100px; margin: 0 auto; position: relative; }
        .dl-eyebrow {
          font-family: 'IBM Plex Mono', monospace; font-size: 11px; letter-spacing: 0.14em; text-transform: uppercase;
          color: rgba(255,255,255,0.4); margin-bottom: 16px; display: flex; align-items: center; gap: 10px;
        }
        .dl-eyebrow::before { content: ''; width: 24px; height: 1px; background: rgba(255,255,255,0.25); }
        .dl-title { font-family: 'Source Serif 4', Georgia, serif; font-size: clamp(26px, 3vw, 40px); font-weight: 300; line-height: 1.2; margin-bottom: 14px; }
        .dl-title em { font-style: italic; color: rgba(255,255,255,0.6); }
        .dl-sub { font-size: 14px; color: rgba(255,255,255,0.55); max-width: 540px; line-height: 1.75; font-weight: 300; }

        .dl-body { background: #F3F3F1; padding: 56px 48px 72px; }
        .dl-label { font-family: 'IBM Plex Mono', monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: #c93333; margin-bottom: 10px; }
        .dl-h2 { font-family: 'Source Serif 4', Georgia, serif; font-size: clamp(20px, 2vw, 26px); font-weight: 400; color: #2a2a2a; margin-bottom: 32px; }

        .dl-cards {
          display: grid; grid-template-columns: 1fr 1fr; gap: 1px; background: #cccac4;
          border: 1px solid #cccac4; border-radius: 8px; overflow: hidden; margin-bottom: 32px;
        }
        .dl-card { background: #fff; padding: 32px 30px; display: flex; flex-direction: column; }
        .dl-card-top { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 18px; }
        .dl-icon {
          width: 48px; height: 48px; border-radius: 10px; background: #f0ede6; color: #c93333;
          display: flex; align-items: center; justify-content: center;
          font-family: 'IBM Plex Mono', monospace; font-size: 11px; letter-spacing: 0.06em;
        }
        .dl-card-title { font-family: 'Source Serif 4', Georgia, serif; font-size: 20px; color: #2a2a2a; margin-bottom: 8px; }
        .dl-card-desc { font-size: 13.5px; color: #6b6b6b; line-height: 1.7; margin-bottom: 24px; flex: 1; }
        .dl-meta { display: flex; flex-direction: column; gap: 8px; padding: 16px 0; border-top: 1px solid #eeecea; border-bottom: 1px solid #eeecea; margin-bottom: 24px; }
        .dl-row { display: flex; justify-content: space-between; align-items: center; }
        .dl-key { font-size: 11px; color: #999; font-family: 'IBM Plex Mono', monospace; letter-spacing: 0.05em; text-transform: uppercase; }
        .dl-val { font-size: 12.5px; color: #444; font-weight: 500; font-variant-numeric: tabular-nums; }
        .dl-btn {
          display: flex; align-items: center; justify-content: center; gap: 8px; background: #2a2a2a; color: #fff;
          font-size: 13px; font-weight: 500; letter-spacing: 0.04em; padding: 11px 24px; border-radius: 6px;
          text-decoration: none; transition: background 0.15s, transform 0.1s;
        }
        .dl-btn:hover { background: #111; transform: translateY(-1px); }
        .dl-btn[aria-disabled="true"] { background: #b9b5ac; pointer-events: none; }

        .dl-cols { background: #fff; border: 1px solid #e4e1dc; border-radius: 8px; padding: 24px 28px; margin-bottom: 20px; }
        .dl-cols-title { font-size: 13px; font-weight: 500; color: #2a2a2a; margin-bottom: 12px; }
        .dl-chips { display: flex; flex-wrap: wrap; gap: 6px; }
        .dl-chips span {
          font-family: 'IBM Plex Mono', monospace; font-size: 11px; color: #4a4a4a;
          background: #f4f2ee; border-radius: 10px; padding: 3px 10px;
        }
        .dl-note { font-size: 12.5px; color: #6b6b6b; line-height: 1.7; }
        .dl-error { font-size: 13px; color: #a80000; margin-bottom: 20px; }

        @media (max-width: 720px) {
          .dl-hero { padding: 40px 20px 44px; }
          .dl-body { padding: 40px 20px 56px; }
          .dl-cards { grid-template-columns: 1fr; }
        }
      `}</style>

      <section className="dl-hero">
        <div className="dl-inner">
          <p className="dl-eyebrow">Download</p>
          <h1 className="dl-title">Get the <em>ADAM2 dataset</em></h1>
          <p className="dl-sub">
            Every entry in the database, generated from the current release each time you
            download — so the files always match what you see on the site.
          </p>
        </div>
      </section>

      <section className="dl-body">
        <div className="dl-inner">
          <p className="dl-label">Files</p>
          <h2 className="dl-h2">Choose a format</h2>

          {failed && (
            <p className="dl-error">
              The download server could not be reached. Make sure the backend is running, then reload this page.
            </p>
          )}

          <div className="dl-cards">
            {files.map((f) => (
              <div className="dl-card" key={f.id}>
                <div className="dl-card-top">
                  <div className="dl-icon">{f.badge}</div>
                </div>
                <p className="dl-card-title">{f.title}</p>
                <p className="dl-card-desc">{f.desc}</p>
                <div className="dl-meta">
                  {(f.meta || [["Status", failed ? "Unavailable" : "Loading…"]]).map(([k, v]) => (
                    <div className="dl-row" key={k}>
                      <span className="dl-key">{k}</span>
                      <span className="dl-val">{v}</span>
                    </div>
                  ))}
                </div>
                <a className="dl-btn" href={f.href} aria-disabled={!info} download>
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M12 3v12M7 10l5 5 5-5M5 21h14" />
                  </svg>
                  {f.cta}
                </a>
              </div>
            ))}
          </div>

          {info && (
            <div className="dl-cols">
              <p className="dl-cols-title">Columns in the CSV</p>
              <div className="dl-chips">
                {info.columns.map((c) => <span key={c}>{c}</span>)}
              </div>
            </div>
          )}

          <p className="dl-note">
            Generated from <strong>{info ? info.sourceFile : "the current database release"}</strong>.
            Entries are aggregated from public antimicrobial-peptide databases; please cite the
            original sources listed in each entry&apos;s <em>source_databases</em> column when using the data.
          </p>
        </div>
      </section>
    </>
  );
}
